    i = 0
    n = len(s)

    while i < n:
        # Skip non-digit characters
        while i < n and not s[i].isdigit():
            i += 1
        if i >= n:
            break

        # Parse number
        start = i
        while i < n and s[i].isdigit():
            i += 1
        num = int(s[start:i])

        # Parse unit if present
        if i < n and s[i] in 'hms':
            unit = s[i]
            i += 1
            if unit == 'h':
                total += num * 3600
            elif unit == 'm':
                total += num * 60
            else:
                total += num
        else:
            total += num

    return total
